'use strict';
let arena=null, speech={text:'',until:0}, aim={x:0,y:-1};
const HUNTS={forest:{name:'잎뿔 괴수',room:'나무 고리 공터',part:'잎뿔',reward:90,material:'잎뿔 조각',desc:'몸을 부풀린 뒤 돌진합니다. 앞쪽 잎뿔을 깨면 돌진이 느려져요.'},cave:{name:'돌껍질 괴수',room:'메아리 동굴',part:'돌껍질',reward:120,material:'껍질 파편',desc:'주변으로 돌조각을 쏩니다. 등껍질을 깨면 탄환 수가 줄어들어요.'}};
const HUNT_PRESETS={easy:{scale:3,attackSpeed:2,maxHp:90,hitbox:1,damage:10,moveSpeed:60},hard:{scale:3,attackSpeed:4,maxHp:180,hitbox:1,damage:18,moveSpeed:80}};
function sayHungry(){speech={text:s.energy<=0?'배가 고파… 아무 의욕이 없어.':'기운이 모자라… 뭔가 먹고 싶어.',until:time+3};tone(180,.08);}
function spendEnergy(n){if(s.energy<n){sayHungry();return false;}s.energy=Math.max(0,s.energy-n);if(s.energy===0)sayHungry();return true;}
function huntDesk(){const used=s.lastHuntDay===s.day;show(head('토벌 담당 갑옷 씨','준비하고, 무사히 돌아와.',`토벌은 하루 한 번. 출발할 때 행동력 20을 사용해요. ${used?'오늘 출정은 마쳤어요. 동굴에서 자고 내일 다시 와요.':'의뢰를 고른 뒤 북쪽 토벌의 문으로 가세요.'}`)+`<div class="cardgrid">${Object.entries(HUNTS).map(([id,h])=>`<div class="item"><h3>${h.name}</h3><p>${h.room}<br>${h.desc}</p><p>보상 ${h.reward}코인 · ${h.material}<br>부위 파괴 추가 보상 20코인</p><button data-act="hunt-accept-${id}" ${used?'disabled':''}>${s.huntQuest===id?'수주 완료 · 다시 선택':'토벌 수주'}</button></div>`).join('')}</div><div class="note">수주는 기회를 소모하지 않아요. 게이트에서 출정하면 승리·실패·철수 모두 오늘의 기회를 사용합니다.<br>이동 WASD · 공격 J / 마우스 클릭 · 회피 Shift / Space · 도시락 F</div>`,'hunter');}
function huntGate(){const h=HUNTS[s.huntQuest];show(head('토벌의 문',h?`${h.room}으로 출발할까?`:'먼저 토벌을 수주해 주세요.',h?`${h.name} · 현재 행동력 ${Math.floor(s.energy)} / 출발 비용 20`:'문 아래쪽에 있는 토벌 담당 갑옷 씨에게 이야기해 보세요.')+`<div class="note">${s.lastHuntDay===s.day?'오늘의 토벌 기회를 사용했어요. 동굴에서 자면 다시 출정할 수 있어요.':'입장하면 오늘의 토벌 기회가 사용됩니다. 음식과 장비를 확인하세요.'}</div><div class="actions"><button class="primary" data-act="hunt-start" ${!h||s.lastHuntDay===s.day||s.energy<20?'disabled':''}>토벌 시작</button><button data-act="close">아직 준비할게요</button></div>`,'gate');}
function acceptHunt(id){if(!HUNTS[id]||s.lastHuntDay===s.day)return;s.huntQuest=id;save();close();toast(`${HUNTS[id].name} 수주 완료. 북쪽 토벌의 문으로 가세요!`);guideT=15;}
function startHunt(){
 if(arena||!HUNTS[s.huntQuest]||s.lastHuntDay===s.day)return false;
 if(!spendEnergy(20))return false;
 const kind=s.huntQuest;s.lastHuntDay=s.day;s.huntInProgress=true;s.x=1470;s.y=345;close();
 const cfg={...HUNT_PRESETS.easy,...s.huntTune};
 arena={kind,cfg,phase:'enter',phaseT:1,player:{x:500,y:650,inv:0,roll:0,rollX:0,rollY:-1,cool:0,attack:0,attackCD:0},boss:{x:500,y:290,hp:cfg.maxHp,partHp:30,broken:false,state:'idle',timer:1,tx:0,ty:0,flash:0},bullets:[],effects:[],attacks:true,movement:true,hitboxes:false,god:false,paid:false,notice:'',noticeT:0,cycle:0};
 walkTarget=null;keys.clear();aim={x:0,y:-1};save();document.body.classList.add('in-hunt');$('#huntHud').hidden=false;buildHuntAdmin();updateHuntUI();return true;
}
function buildHuntAdmin(){const a=arena;if(!a)return;$('#huntAdmin').innerHTML=`<summary>⚙ <span>전투 조정</span></summary><p>실시간 적용 · 값은 다음 출정에도 유지</p><div class="preset"><button data-hunt-config="easy">쉬움</button><button data-hunt-config="hard">어려움</button></div>${[['scale','보스 크기',1,5,.1],['attackSpeed','공격 속도',.5,6,.1],['maxHp','보스 최대 HP',10,500,10],['hitbox','피격 범위 배율',.4,2,.1],['damage','보스 공격 피해',1,50,1],['moveSpeed','보스 이동 속도',0,140,5]].map(([id,label,min,max,step])=>`<label>${label}<input aria-label="${label}" type="number" data-tune="${id}" min="${min}" max="${max}" step="${step}" value="${a.cfg[id]}"></label>`).join('')}<label>보스 공격<input type="checkbox" data-switch="attacks" ${a.attacks?'checked':''}></label><label>보스 이동<input type="checkbox" data-switch="movement" ${a.movement?'checked':''}></label><label>판정 범위 표시<input type="checkbox" data-switch="hitboxes" ${a.hitboxes?'checked':''}></label><label>플레이어 무적<input type="checkbox" data-switch="god" ${a.god?'checked':''}></label><div class="preset"><button data-reset="boss">보스 HP·부위 초기화</button><button data-reset="player">내 HP 초기화</button></div><small>HP 변경은 현재 체력 비율을 유지합니다.<br>초기화는 전투 중에만 가능해요.</small>`;}
function setHuntTune(id,value){if(!arena)return;const limits={scale:[1,5],attackSpeed:[.5,6],maxHp:[10,500],hitbox:[.4,2],damage:[1,50],moveSpeed:[0,140]};if(!limits[id]||!Number.isFinite(value))return;let [lo,hi]=limits[id],v=Math.max(lo,Math.min(hi,value));if(id==='maxHp')arena.boss.hp=Math.max(0,arena.boss.hp/arena.cfg.maxHp*v);arena.cfg[id]=v;s.huntTune={...arena.cfg};save();}
function setHuntSwitch(id,v){if(!arena||!['attacks','movement','hitboxes','god'].includes(id))return;arena[id]=v;if(id==='attacks'&&!v){arena.bullets=[];arena.boss.state='idle';arena.boss.timer=1;}if(id==='movement'&&!v&&arena.boss.state==='charge'){arena.boss.state='rest';arena.boss.timer=1;}}
function resetHunt(who){if(!arena||arena.phase!=='fight')return;if(who==='player')s.hp=100;else if(who==='boss'){arena.boss.hp=arena.cfg.maxHp;arena.boss.partHp=30;arena.boss.broken=false;arena.boss.state='idle';arena.boss.timer=1;arena.bullets=[];}save();}
function huntNotice(t){arena.notice=t;arena.noticeT=3;}
function arenaRadius(){return 24*arena.cfg.scale;}
function partPosition(){const b=arena.boss,r=arenaRadius();return arena.kind==='forest'?{x:b.x,y:b.y-r*.9}:{x:b.x+r*.6,y:b.y-r*.2};}
function hurtBoss(damage,part){const a=arena;if(!a||a.phase!=='fight'||a.boss.hp<=0)return;const b=a.boss;b.hp=Math.max(0,b.hp-damage);b.flash=.15;if(part&&!b.broken){b.partHp=Math.max(0,b.partHp-damage);if(b.partHp===0){b.broken=true;b.state='rest';b.timer=1.6;a.bullets=[];huntNotice(`${HUNTS[a.kind].part} 파괴! ${a.kind==='forest'?'돌진이 느려졌어요.':'탄환이 줄었어요.'}`);tone(820,.2);}}if(b.hp<=0)winHunt();}
function huntAttack(){const a=arena;if(!a||a.phase!=='fight'||modal.open||a.player.attackCD>0)return;if(!spendEnergy(1))return;const p=a.player;p.attack=.22;p.attackCD=.38;attackT=.22;const len=Math.hypot(aim.x,aim.y)||1,ax=aim.x/len,ay=aim.y/len;const sx=p.x+ax*48,sy=p.y+ay*48,r=arenaRadius()*a.cfg.hitbox,part=partPosition();a.effects.push({x:sx,y:sy,t:.22,angle:Math.atan2(ay,ax)});if(Math.hypot(part.x-sx,part.y-sy)<32+20*a.cfg.scale*.5&&!a.boss.broken)hurtBoss(8,true);else if(Math.hypot(a.boss.x-sx,a.boss.y-sy)<r+32)hurtBoss(8,false);tone(300,.04);}
function huntDodge(){const a=arena;if(!a||a.phase!=='fight'||modal.open||a.player.cool>0)return;if(!spendEnergy(1))return;const p=a.player;let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(!dx&&!dy){dx=aim.x;dy=aim.y;}let l=Math.hypot(dx,dy)||1;p.rollX=dx/l;p.rollY=dy/l;p.roll=.25;p.inv=.35;p.cool=.65;}
function huntEat(){if(!arena||arena.phase!=='fight'||modal.open)return;if(!s.food){speech={text:'도시락이 없어…',until:time+3};return;}s.food--;s.energy=Math.min(100,s.energy+35);s.hp=Math.min(100,s.hp+15);huntNotice('도시락을 먹었어요. 행동력 +35 · 체력 +15');save();}
function hurtHunter(damage){if(!arena||arena.phase!=='fight'||arena.god||arena.player.inv>0)return;s.hp=Math.max(0,s.hp-damage);arena.player.inv=.8;tone(130,.1);if(s.hp<=0)beginRescue('체력을 모두 잃었어요.');}
function winHunt(){const a=arena;if(!a||a.phase!=='fight')return;a.phase='won';a.bullets=[];keys.clear();const h=HUNTS[a.kind],bonus=a.boss.broken?20:0;if(!a.paid){s.coins+=h.reward+bonus;s.tokens++;s.materials??={};s.materials[h.material]=(s.materials[h.material]||0)+1;a.paid=true;save();}a.notice=`토벌 성공 · ${h.reward+bonus}코인 + ${h.material} 1개 + 증표 1개${bonus?' (부위 파괴 +20코인 포함)':''}`;a.noticeT=999;toast('출구가 열렸어요. 남쪽 문까지 걸어가 E를 누르세요.');tone(880,.3);}
function askRescue(){if(!arena||!['fight','enter'].includes(arena.phase)||modal.open)return;keys.clear();show(head('대나무 구조 헬리콥터','도망가시겠습니까?','철수하면 토벌 실패로 처리돼요. 오늘의 토벌 기회와 사용한 행동력은 돌아오지 않습니다.')+'<div class="actions"><button class="primary" data-act="rescue-yes">예, 구조해 주세요</button><button data-act="close">아니요, 계속 싸울게요</button></div>','rescue-confirm');}
function beginRescue(reason){if(!arena||!['fight','enter'].includes(arena.phase))return;if(modal.open)close();arena.phase='rescue';arena.phaseT=0;arena.reason=reason;arena.bullets=[];keys.clear();arena.player.attack=0;attackT=0;save();}
function leaveHunt(){const a=arena;if(!a)return;if(a.phase!=='won'&&a.phase!=='rescue')return;s.x=1470;s.y=345;if(a.phase==='rescue')s.hp=Math.max(35,s.hp);s.huntInProgress=false;s.huntQuest=null;arena=null;keys.clear();walkTarget=null;encounterCooldown=4;cam.x=s.x;cam.y=s.y;document.body.classList.remove('in-hunt');$('#huntHud').hidden=true;save();toast('토벌의 문 앞에 도착했어요. 오늘은 쉬고 내일 다시 만나요.');}
function arenaInteract(){if(arena?.phase==='won'&&Math.hypot(arena.player.x-500,arena.player.y-725)<85)leaveHunt();}
function clampArena(o,margin){const cx=500,cy=420,rx=445-margin,ry=335-margin;let nx=(o.x-cx)/rx,ny=(o.y-cy)/ry,l=Math.hypot(nx,ny);if(l>1){o.x=cx+nx/l*rx;o.y=cy+ny/l*ry;}}
function updateArena(dt){const a=arena;if(!a||modal.open)return;if(a.phase==='enter'){a.phaseT-=dt;if(a.phaseT<=0)a.phase='fight';return;}if(a.phase==='rescue'){a.phaseT+=dt;if(a.phaseT>4.5)leaveHunt();return;}const p=a.player,b=a.boss;a.noticeT=Math.max(0,a.noticeT-dt);p.inv=Math.max(0,p.inv-dt);p.cool=Math.max(0,p.cool-dt);p.roll=Math.max(0,p.roll-dt);p.attackCD=Math.max(0,p.attackCD-dt);p.attack=Math.max(0,p.attack-dt);attackT=p.attack;b.flash=Math.max(0,b.flash-dt);let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);moving=!!(dx||dy);if(p.roll>0){p.x+=p.rollX*520*dt;p.y+=p.rollY*520*dt;}else if(moving){let l=Math.hypot(dx,dy);p.x+=dx/l*180*dt;p.y+=dy/l*180*dt;face=Math.abs(dx)>Math.abs(dy)?dx<0?'left':'right':dy<0?'back':'front';if(!a.pointerAim){aim.x=dx/l;aim.y=dy/l;}}clampArena(p,18);a.effects=a.effects.filter(e=>(e.t-=dt)>0);if(a.phase==='won')return;
 const dist=Math.hypot(p.x-b.x,p.y-b.y)||1,rate=a.cfg.attackSpeed/2;b.timer-=dt*rate;
 if(b.state==='idle'){
  if(a.movement&&dist>130){b.x+=(p.x-b.x)/dist*a.cfg.moveSpeed*dt;b.y+=(p.y-b.y)/dist*a.cfg.moveSpeed*dt;}
  if(a.attacks&&b.timer<=0){b.state=a.kind==='forest'?'windup':'cast';b.timer=1.15;b.tx=(p.x-b.x)/dist;b.ty=(p.y-b.y)/dist;a.cycle++;}
 }else if(b.state==='windup'&&b.timer<=0){b.state='charge';b.timer=.7;}
 else if(b.state==='charge'){
  if(a.movement){let v=b.broken?190:340;b.x+=b.tx*v*dt;b.y+=b.ty*v*dt;}
  if(Math.hypot(p.x-b.x,p.y-b.y)<arenaRadius()*a.cfg.hitbox+15)hurtHunter(a.cfg.damage);
  if(b.timer<=0){b.state='rest';b.timer=1.1;}
 }else if(b.state==='cast'&&b.timer<=0){const count=b.broken?5:10;for(let i=0;i<count;i++){let angle=i*Math.PI*2/count+a.cycle*.35;a.bullets.push({x:b.x,y:b.y,vx:Math.cos(angle)*150,vy:Math.sin(angle)*150,t:4});}b.state='rest';b.timer=1.2;}
 else if(b.state==='rest'&&b.timer<=0){b.state='idle';b.timer=.8;}
 clampArena(b,arenaRadius());
 for(const q of a.bullets){q.x+=q.vx*dt;q.y+=q.vy*dt;q.t-=dt;if(Math.hypot(q.x-p.x,q.y-p.y)<14+8*a.cfg.hitbox){hurtHunter(a.cfg.damage);q.t=0;}}a.bullets=a.bullets.filter(q=>q.t>0);
 if(a.phase==='fight'){let d=Math.hypot(p.x-b.x,p.y-b.y),min=arenaRadius()*.65+15;if(d<min&&p.roll<=0){const ux=(p.x-b.x)/(d||1),uy=(p.y-b.y)/(d||1);p.x=b.x+ux*min;p.y=b.y+uy*min;clampArena(p,18);}}
}
function arenaTransform(){const scale=Math.min(sw/1060,sh/900);return{scale,x:sw/2-500*scale,y:sh/2-410*scale};}
function arenaPointer(e,attackNow=false){if(!arena)return;const t=arenaTransform();aim.x=(e.clientX-t.x)/t.scale-arena.player.x;aim.y=(e.clientY-t.y)/t.scale-arena.player.y;arena.pointerAim=true;if(attackNow)huntAttack();}
function drawHuntBoss(c){const a=arena,b=a.boss,k=a.cfg.scale;c.save();c.translate(b.x,b.y);c.scale(k,k);shadow(c,0,0,29);let fill=b.flash>0?'#ffecba':a.kind==='forest'?'#7e9a59':'#a39c8b';ellipse(c,0,-12,29,23,fill,'#394a34',1.6);if(a.kind==='forest'){for(let i=0;i<5;i++){let x=-24+i*12;shape(c,[[x,-21],[x-8,-38],[x+8,-31]],'#66824e','#394a34',1);}ellipse(c,-19,7,10,5,'#68834b');ellipse(c,20,7,10,5,'#68834b');if(!b.broken){shape(c,[[-13,-29],[-18,-50],[-4,-39],[0,-58],[7,-37],[18,-49],[14,-27]],'#cad389','#46543b',1.5);}else line(c,[[-10,-30],[0,-25],[10,-30]],'#efdfb1',2);}else{shape(c,[[-24,-25],[-17,-39],[4,-45],[27,-29],[29,-2],[10,9],[-17,3]],'#858b88','#3f4845',1.6);line(c,[[-17,-29],[3,-35],[17,-23],[13,-5],[-7,-1],[-17,-16],[2,-22],[7,-12]],'#bec0ae',2);if(b.broken)line(c,[[-20,-34],[-5,-21],[-12,-10],[13,5]],'#e8d3a2',4);}
 ellipse(c,-10,-10,6,7,'#f0e8c3','#394a34',1);ellipse(c,11,-10,6,7,'#f0e8c3','#394a34',1);ellipse(c,-9,-9,2,3,'#313e30',null);ellipse(c,10,-9,2,3,'#313e30',null);line(c,[[-6,0],[0,3],[6,0]],'#394a34',1.5);c.restore();}
function drawRescue(c){const a=arena,p=a.player,t=a.phaseT;let hookY=t<1.3?p.y-240+(t/1.3)*175:p.y-65-Math.max(0,t-2)*150;let lift=t>2?(t-2)*150:0;if(t>1.3){c.save();c.globalAlpha=Math.max(0,1-(t-3.7));character(c,p.x,p.y-lift,{wear:s.wear,dir:'front'});c.restore();}c.save();c.translate(p.x,hookY);line(c,[[0,-15],[0,-47]],'#725c40',5);ellipse(c,0,-47,40,8,'#bfc58e','#525b3a',2);line(c,[[-Math.cos(time*32)*54,-49],[Math.cos(time*32)*54,-45]],'#717947',5);shape(c,[[-18,0],[-25,10],[-23,25],[-15,13],[-11,7]],'#c5cbb8');shape(c,[[18,0],[25,10],[23,25],[15,13],[11,7]],'#c5cbb8');line(c,[[-17,0],[0,-14],[17,0]],'#52614c',4);c.restore();}
function drawSpeech(c,x,y){if(time>speech.until)return;c.font="14px 'Noto Sans KR'";let w=c.measureText(speech.text).width+28;c.fillStyle='#fff9e8';c.beginPath();c.roundRect(x-w/2,y-112,w,34,10);c.fill();shape(c,[[x-6,y-79],[x,y-70],[x+6,y-79]],'#fff9e8',null);text(c,speech.text,x,y-90,14);}
function renderArena(){const a=arena;if(!a)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle=a.kind==='forest'?'#2f4838':'#292e35';ctx.fillRect(0,0,sw,sh);const t=arenaTransform();ctx.save();ctx.translate(t.x,t.y);ctx.scale(t.scale,t.scale);ctx.save();ctx.beginPath();ctx.ellipse(500,420,448,338,0,0,Math.PI*2);ctx.clip();if(a.kind==='forest'&&bg.complete&&bg.naturalWidth)ctx.drawImage(bg,30,60,940,730);else{ctx.fillStyle='#787c77';ctx.fillRect(30,60,940,730);for(let i=0;i<45;i++){let x=90+(i*137)%820,y=100+(i*93)%630;line(ctx,[[x,y],[x+22,y-8],[x+40,y+5]],'#626965',2);}}ctx.restore();for(let i=0;i<24;i++){let an=i*Math.PI*2/24,x=500+Math.cos(an)*450,y=420+Math.sin(an)*338;if(Math.abs(x-500)<100&&y>680)continue;if(a.kind==='forest')tree(ctx,{x,y,size:.7,variant:0});else{shape(ctx,[[x-27,y],[x-34,y-35],[x-12,y-65],[x+20,y-53],[x+34,y-8]],'#535e5d','#303d3b',3);}}const open=a.phase==='won';ellipse(ctx,500,735,58,17,open?'#d7edac':'#535d4b','#303d33',3);text(ctx,open?'출구 · 가까이에서 E':'봉인된 출구',500,778,16,open?'#edffc9':'#d1d0bc');
 const b=a.boss,p=a.player;if(['windup','cast'].includes(b.state)&&a.phase==='fight'){if(b.state==='windup'){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.atan2(b.ty,b.tx));ctx.fillStyle='#dc705052';ctx.fillRect(0,-arenaRadius(),330,arenaRadius()*2);ctx.restore();}else ellipse(ctx,b.x,b.y,170,170,'#d3935b22','#e4a876',3);}
 if(a.phase==='won'){ctx.globalAlpha=.35;drawHuntBoss(ctx);ctx.globalAlpha=1;}else drawHuntBoss(ctx);
 if(a.phase!=='rescue'||a.phaseT<1.3){ctx.save();if(p.inv>0&&Math.floor(time*15)%2)ctx.globalAlpha=.5;character(ctx,p.x,p.y,{dir:face,walk:moving,wear:s.wear});ctx.restore();}
 for(const q of a.bullets)ellipse(ctx,q.x,q.y,9,9,'#e5c69a','#715c46',2);
 for(const e of a.effects){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.angle);ctx.strokeStyle='#fff0c4';ctx.lineWidth=7;ctx.beginPath();ctx.arc(-23,0,48,-.9,.9);ctx.stroke();ctx.restore();}
 if(!b.broken&&a.phase==='fight'){const part=partPosition();ellipse(ctx,part.x,part.y,14,14,'#f8dfa329','#f1d986',2);text(ctx,HUNTS[a.kind].part,part.x,part.y-23,12,'#fff8d0');}if(a.hitboxes){ellipse(ctx,b.x,b.y,arenaRadius()*a.cfg.hitbox,arenaRadius()*a.cfg.hitbox,'#ef75551a','#f58f68',2);ellipse(ctx,p.x,p.y,18,18,'#6398ff22','#9ac6ff',2);const part=partPosition();ellipse(ctx,part.x,part.y,30,30,'#f3dc5622','#f8ec87',2);text(ctx,HUNTS[a.kind].part,part.x,part.y-37,13,'#ffffbc');}
 if(a.phase==='rescue')drawRescue(ctx);drawSpeech(ctx,p.x,p.y);ctx.restore();if(a.phase==='enter'){ctx.fillStyle=`rgba(25,37,29,${Math.max(0,a.phaseT)})`;ctx.fillRect(0,0,sw,sh);}if(a.phase==='rescue'){text(ctx,'토벌 실패',sw/2,sh*.28,36,'#fff3db');text(ctx,a.reason+' 구조 헬리콥터가 데려다줘요.',sw/2,sh*.28+35,15,'#fff3db');}}
function updateHuntUI(){const a=arena;if(!a)return;$('#huntTitle').textContent=HUNTS[a.kind].name+' · '+HUNTS[a.kind].room;$('#bossHp').textContent=`${Math.ceil(a.boss.hp)} / ${a.cfg.maxHp}`;$('#bossBar').style.width=(a.boss.hp/a.cfg.maxHp*100)+'%';$('#partText').textContent=a.boss.broken?`${HUNTS[a.kind].part} 파괴 완료`:`${HUNTS[a.kind].part} ${a.boss.partHp} / 30`;$('#hunterVitals').textContent=`♥ ${Math.ceil(s.hp)} / 100　✦ 행동력 ${Math.floor(s.energy)} / 100　도시락 ${s.food}`;$('#huntNotice').textContent=a.noticeT>0?a.notice:a.phase==='won'?'남쪽 출구가 열렸어요. 걸어가 E를 누르세요.':'WASD 이동 · J / 클릭 공격 · Shift / Space 회피 · F 도시락';$('#rescueButton').disabled=!['fight','enter'].includes(a.phase);$('#huntEat').disabled=a.phase!=='fight'||!s.food;}
function huntWorldObject(c,o){if(o.type!=='gate')return false;c.save();c.translate(o.x,o.y);shadow(c,0,0,70);shape(c,[[-65,0],[-65,-130],[-48,-140],[-45,0]],'#aaa886');shape(c,[[45,0],[48,-140],[65,-130],[65,0]],'#aaa886');shape(c,[[-78,-125],[-50,-152],[50,-152],[78,-125]],'#65775c');ellipse(c,0,-72,43,63,'#364c4144','#ccd3b0',3);line(c,[[-44,-52],[44,-52]],'#8f9f77',3);text(c,'討伐',0,-115,16,'#fff4c8');c.restore();label(o.name,o.x,o.y+27);return true;}
